begin;

create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
select plan(29);

select has_table('consulting_os', 'roles', 'Role is a typed Phase 6 table');
select has_table('consulting_os', 'workflow_versions', 'Workflow has explicit immutable versions');
select has_table('consulting_os', 'capability_requirements', 'Capability Requirement is first-class');
select has_table('consulting_os', 'capability_maturity_assessments', 'Readiness and maturity evidence is first-class');
select has_view('consulting_os', 'role_architecture', 'Complete role composition has a secure projection');
select has_view('consulting_os', 'capability_pathways', 'Capability trace has a secure projection');
select has_view('consulting_os', 'my_capability_pathways', 'Client development uses a current-person projection');
select results_eq(
  $$select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'consulting_os' and c.relname in ('roles','role_assignments','responsibilities','authorities','boundaries','interfaces','workflow_versions','capability_requirements','capability_assessments','capability_gaps','development_plans','practices','capability_maturity_assessments') and c.relrowsecurity$$,
  array[13::bigint], 'All material Phase 6 typed tables enforce RLS');






set constraints all immediate;

select results_eq($$select count(*) from consulting_os.role_architecture where id = '94000000-0000-4000-8000-000000000003' and jsonb_array_length(responsibilities) = 1 and jsonb_array_length(authorities) = 1 and jsonb_array_length(boundaries) = 1 and jsonb_array_length(interfaces) = 1$$, array[1::bigint], 'Role composes purpose, responsibility, authority, boundary, interface, support, accountability, and measures');
select results_eq($$select count(*) from consulting_os.entity_relationships where source_id = '94000000-0000-4000-8000-000000000001' and target_id = '94000000-0000-4000-8000-000000000002' and relationship_type = 'INFORMS'$$, array[1::bigint], 'Validated Insight traces into Decision');
select results_eq($$select count(*) from consulting_os.entity_relationships where source_id = '94000000-0000-4000-8000-000000000002' and target_id = '94000000-0000-4000-8000-000000000003' and relationship_type = 'CREATES'$$, array[1::bigint], 'Decision traces into concrete role design');
select results_eq($$select count(*) from consulting_os.current_workflow_versions w join consulting_os.workflow_steps s on s.workflow_version_id = w.id where w.id = '94000000-0000-4000-8000-000000000014' and s.decision_point$$, array[1::bigint], 'Current workflow preserves ordered decision points');
select results_eq($$select count(*) from consulting_os.capability_pathways where requirement_id = '94000000-0000-4000-8000-000000000016' and required_level = 'RELIABLE' and current_level = 'DEVELOPING' and development_plan_id = '94000000-0000-4000-8000-000000000019'$$, array[1::bigint], 'Capability pathway compares requirement with evidence-based current state');
select results_eq($$select count(*) from consulting_os.capability_assessment_evidence where assessment_id = '94000000-0000-4000-8000-000000000017'$$, array[1::bigint], 'Capability assessment retains evidence');
select results_eq($$select count(*) from consulting_os.capability_maturity_evidence where maturity_assessment_id = '94000000-0000-4000-8000-000000000023'$$, array[1::bigint], 'Development traces forward to maturity evidence without inferring maturity');
select results_eq($$select count(*) from consulting_os.entity_relationships where relationship_type in ('INFORMS','CREATES','REQUIRES','DEVELOPS') and organization_id = '9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, array[4::bigint], 'Canonical Phase 6 reasoning edges persist');
select throws_ok($$update consulting_os.roles set purpose = 'Rewrite meaning' where id = '94000000-0000-4000-8000-000000000003'$$, '55000', null, 'Meaning-changing Role edits require a new version');
select throws_ok($$insert into consulting_os.capability_requirements (id,organization_id,engagement_id,capability_id,source_domain_object_id,source_type,target_subject_id,required_level,rationale,created_by) values (gen_random_uuid(),'9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','93000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000015','94000000-0000-4000-8000-000000000003','WORKFLOW','94000000-0000-4000-8000-000000000005','RELIABLE','Wrong type','92000000-0000-4000-8000-000000000001')$$, null, null, 'Requirement source type cannot contradict its domain object');
select throws_ok($$insert into consulting_os.capability_gaps (id,organization_id,engagement_id,requirement_id,assessment_id,required_level,current_level,gap_statement,priority,created_by) values (gen_random_uuid(),'9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','93000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000016','94000000-0000-4000-8000-000000000017','TRANSFERABLE','FOUNDATIONAL','Contradict source levels','HIGH','92000000-0000-4000-8000-000000000001')$$, null, null, 'Gap cannot contradict requirement and assessment levels');
select throws_ok($$insert into consulting_os.interfaces (id,organization_id,logical_id,version_number,source_role_id,target_role_id,purpose,inputs,outputs,operating_rules,cadence,effective_from,created_by) values (gen_random_uuid(),'9bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',gen_random_uuid(),1,'94000000-0000-4000-8000-000000000003','94000000-0000-4000-8000-000000000004','Cross tenant','x','y','z','weekly',now(),'92000000-0000-4000-8000-000000000003')$$, null, null, 'Role architecture cannot cross tenant boundaries');
select throws_ok($$insert into consulting_os.capability_maturity_evidence (organization_id,maturity_assessment_id,evidence_domain_object_id,relevance,created_by) values ('9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','94000000-0000-4000-8000-000000000023','94000000-0000-4000-8000-000000000026','Unsafe private evidence promotion.','92000000-0000-4000-8000-000000000001')$$, '42501', null, 'Shared maturity assessment cannot broaden consultant-private evidence visibility');
select ok(not has_table_privilege('authenticated','consulting_os.roles','UPDATE'), 'Authenticated users cannot overwrite versioned Roles');
select ok(has_column_privilege('authenticated','consulting_os.development_activities','status','UPDATE'), 'Authorized development activity state is updateable');

set local role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
select results_eq($$select count(*) from consulting_os.my_capability_pathways where requirement_id = '94000000-0000-4000-8000-000000000016'$$, array[1::bigint], 'Client sees only the pathway attached to their active Role Assignment');
select results_eq($$select count(*) from consulting_os.role_architecture where id = '94000000-0000-4000-8000-000000000003'$$, array[1::bigint], 'Client reads the same shared Role object through RLS');

reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000003',true);
select results_eq($$select count(*) from consulting_os.role_architecture where organization_id = '9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, array[0::bigint], 'Other tenant cannot read Role architecture');
select results_eq($$select count(*) from consulting_os.capability_pathways where organization_id = '9aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, array[0::bigint], 'Other tenant cannot read capability pathways');

reset role;
select results_eq($$select count(*) from consulting_os.capability_pathways where requirement_id = '94000000-0000-4000-8000-000000000016' and practice_count = 1$$, array[1::bigint], 'Development Plan traces forward to recorded practice');
select results_eq($$select count(*) from consulting_security.relationship_type_rules where relationship_type in ('CREATES','AUTHORIZES','REQUIRES','DEVELOPS','ENABLES','CONSTRAINS','OWNS')$$, array[33::bigint], 'Controlled relationship vocabulary contains the Phase 6 design and capability rules');

select * from finish();
rollback;
